"""Implementation of operations on the Wave Setup Form window in the Mosaiq application"""
from interops.libraries.squish_actions import CommonActions
from interops.libraries.mosaiq.interactions.objects.mosaiq_schedule_wave_setup_objects import WaveSetupForm
from interops.libraries.common.state import State
from datetime import time, datetime

class WaveSetup():
    """
    Class for TPS Security window operataions.

    Use property getter and setter for each data item.

    """
    def __init__(self) -> None:
        CommonActions.wait_for_object_exists(WaveSetupForm.wave_Setup_Form_Window)

        #Start
        self.start_date = State(WaveSetupForm.start_Date_Edit)
        self.start_time = State(WaveSetupForm.start_Time_Edit)

        #End
        self.after_a_certain_number_of_times = State(WaveSetupForm.after_a_certain_number_of_times_RadioButton)
        self.number_of_times = State(WaveSetupForm.number_of_times_ComboBox)
        self.after_a_certain_amount_of_time = State(WaveSetupForm.after_a_certain_amount_of_time_RadioButton)
        self.amount_of_time = State(WaveSetupForm.amount_of_time_ComboBox)
        self.time_unit = State(WaveSetupForm.time_unit_ComboBox)
        self.by_a_certain_date = State(WaveSetupForm.by_a_certain_date_RadioButton)
        self.end_date = State(WaveSetupForm.end_Date_Edit)
        self.end_time = State(WaveSetupForm.end_Time_Edit)

        #times per day
        self.once = State(WaveSetupForm.once_RadioButton)
        self.bid = State(WaveSetupForm.bID_RadioButton)
        self.tid = State(WaveSetupForm.tID_RadioButton)
        self.times = State(WaveSetupForm.times_RadioButton)
        self.times_per_day = State(WaveSetupForm.times_per_day_ComboBox)
        self.interval_hours = State(WaveSetupForm.interval_Hours_ComboBox)
        self.interval_minutes = State(WaveSetupForm.interval_Minutes_ComboBox)

        #pattern
        self.daily = State(WaveSetupForm.daily_RadioButton)
        self.weekly = State(WaveSetupForm.weekly_RadioButton)
        self.biweekly = State(WaveSetupForm.bi_Weekly_RadioButton)
        self.monthly = State(WaveSetupForm.monthly_RadioButton)
        self.yearly = State(WaveSetupForm.yearly_RadioButton)
        self.every_unit_of_time = State(WaveSetupForm.every_unit_of_time_RadioButton) #Every Day/ Every Week/Every Month
        self.every_other_day = State(WaveSetupForm.every_other_day_RadioButton)
        self.every = State(WaveSetupForm.every_RadioButton)
        self.time_unit_count = State(WaveSetupForm.time_unit_count_ComboBox) # a number of Days/Weeks/Months
        self.on_a_certain_day_of_the_month = State(WaveSetupForm.on_a_certain_day_of_the_month_RadioButton)
        self.on_a_certain_weekday = State(WaveSetupForm.on_a_certain_weekday_RadioButton)
        self.nth_week = State(WaveSetupForm.nth_week_ComboBox)
        self.weekday = State(WaveSetupForm.weekday_ComboBox)
        self.month = State(WaveSetupForm.month_ComboBox)  #January/February/....
        self.sun = State(WaveSetupForm.sun_CheckBox)
        self.mon = State(WaveSetupForm.mon_CheckBox)
        self.tue = State(WaveSetupForm.tue_CheckBox)
        self.wed = State(WaveSetupForm.wed_CheckBox)
        self.thu = State(WaveSetupForm.thu_CheckBox)
        self.fri = State(WaveSetupForm.fri_CheckBox)
        self.sat = State(WaveSetupForm.sat_CheckBox)
        self.second_sun = State(WaveSetupForm.sun_CheckBox_2)
        self.second_mon = State(WaveSetupForm.mon_CheckBox_2)
        self.second_tue = State(WaveSetupForm.tue_CheckBox_2)
        self.second_wed = State(WaveSetupForm.wed_CheckBox_2)
        self.second_thu = State(WaveSetupForm.thu_CheckBox_2)
        self.second_fri = State(WaveSetupForm.fri_CheckBox_2)
        self.second_sat = State(WaveSetupForm.sat_CheckBox_2)
        self.include_saturday = State(WaveSetupForm.saturday_CheckBox)
        self.include_sunday = State(WaveSetupForm.sunday_CheckBox)
        self.include_holidays = State(WaveSetupForm.holidays_CheckBox)
        self.include_blocked_days = State(WaveSetupForm.fully_Blocked_Days_CheckBox)

    def click_ok(self):
        """
        Click button "OK"
        """
        CommonActions.left_click_object(WaveSetupForm.oK_Button)

    def click_cancel(self):
        """
        Click button "Cancel"
        """
        CommonActions.left_click_object(WaveSetupForm.cancel_Button)

    def enter_date(self, year: int, month: int, day: int, start_date: bool):
        """
        Enter formatted date to start or end time edit
        """
        date_text = format_date(year, month, day)
        if start_date:
            self.start_date.value = date_text
        else:
            self.end_date.value = date_text

    def enter_time(self, hour: int, minute: int, start_date: bool):
        """
        Enter formatted time to start or end time edit
        """
        time_text = format_time(hour, minute)
        if start_date:
            self.start_time.value = time_text
        else:
            self.end_time.value = time_text

    def click_date_button(self, start_date: bool):
        """
        Click the date button.
        """
        if start_date:
            CommonActions.left_click_object(WaveSetupForm.start_Date_Button)
        else:
            CommonActions.left_click_object(WaveSetupForm.end_Date_Button)

def format_date(year: int, month: int, day: int):
    """
    Format date to mm/dd/yyyy for the date given by year,month,day
    where month or day does not have leading zero
    """

    try:
        date = datetime(year, month, day)
         # Format the date to mm/dd/yyyy
        formatted_date = date.strftime("%-m/%-d/%Y")
        return formatted_date
    except ValueError:
        return ""

def format_time(hour: int, minute: int):
    """
    Format time to HH:MM AM/PM for the time given by hour(0-23), and minute(0-59)
    where hour does not have leading zero.
    """

    try:
        time_obj = time(hour, minute)
        # Format the time to a string in HH:MM AM/PM format
        formatted_time = time_obj.strftime("%-I:%M %p")
        return formatted_time
    except ValueError:
        return ""